const banknotes = [500, 200, 100, 50, 20, 10, 5];
const coins = [2, 1, 0.5, 0.2, 0.1, 0.05, 0.02, 0.01];
let state = {
  operationType: "TRANSFER_OUT",
  selectedCashRegisterId: "",
  selectedCashRegisterLabel: "",
  note: "",
  cashRegisters: [],
  lines: [...banknotes, ...coins].map(v => ({
    denominationValue: v,
    quantity: 0,
    amount: 0
  })),
  total: 0
};
function money(v) {
  return Number(v || 0).toFixed(2);
}
function getRegisterId(r) {
  return String(r.value || r.cashRegisterId || r.id || "");
}
function getRegisterLabel(r) {
  return r.label || `${r.cashRegisterCode || r.code || ""} - ${r.cashRegisterName || r.name || ""}`;
}
function operationLabel(type) {
  if (type === "TRANSFER_OUT") return "Bank Deposit";
  if (type === "TRANSFER_IN") return "Bank Withdrawal";
  if (type === "IN") return "Cash In";
  if (type === "OUT") return "Cash Out";
  return "Cash Operation";
}
function pushModel() {
  appsmith.updateModel({
    operationType: state.operationType,
    selectedCashRegisterId: state.selectedCashRegisterId,
    selectedCashRegisterLabel: state.selectedCashRegisterLabel,
    note: state.note,
    lines: state.lines,
    total: state.total
  });
}
function calculateOnly() {
  state.total = state.lines.reduce((sum, line) => {
    line.amount = Number(line.quantity || 0) * Number(line.denominationValue || 0);
    return sum + line.amount;
  }, 0);
  document.getElementById("total").innerText = money(state.total);
}
function renderRegisters() {
  const select = document.getElementById("cashRegister");
  const registers = state.cashRegisters.length ? state.cashRegisters : appsmith.model.cashRegisters || [];
  state.cashRegisters = registers;
  document.getElementById("debugInfo").innerText = "Cash registers loaded: " + registers.length;
  select.innerHTML = `<option value="">Select cash register</option>`;
  registers.forEach(r => {
    const option = document.createElement("option");
    option.value = getRegisterId(r);
    option.textContent = getRegisterLabel(r);
    select.appendChild(option);
  });
  select.value = String(state.selectedCashRegisterId || "");
}
function renderMoney(containerId, values) {
  const container = document.getElementById(containerId);
  container.innerHTML = "";
  values.forEach(value => {
    const line = state.lines.find(x => Number(x.denominationValue) === Number(value));
    const row = document.createElement("div");
    row.className = "money-row";
    row.innerHTML = `
      <b>${money(value)} EUR</b>
      <input type="number" min="0" step="1" value="${line.quantity}" data-value="${value}">
      <div class="amount">${money(line.amount)} EUR</div>
    `;
    container.appendChild(row);
  });
  container.querySelectorAll("input").forEach(input => {
    input.addEventListener("input", e => {
      const value = Number(e.target.dataset.value);
      const line = state.lines.find(x => Number(x.denominationValue) === value);
      if (!line) return;
      line.quantity = Number(e.target.value || 0);
      line.amount = line.quantity * line.denominationValue;
      const amountEl = e.target.parentElement.querySelector(".amount");
      if (amountEl) {
        amountEl.innerText = money(line.amount) + " EUR";
      }
      calculateOnly();
      pushModel();
    });
  });
}
function renderAllMoney() {
  renderMoney("banknotes", banknotes);
  renderMoney("coins", coins);
  calculateOnly();
}
function bindEvents() {
  document.getElementById("operationType").addEventListener("change", e => {
    state.operationType = e.target.value;
    pushModel();
  });
  document.getElementById("cashRegister").addEventListener("change", e => {
    const selectedId = String(e.target.value || "");
    state.selectedCashRegisterId = selectedId;
    const selected = state.cashRegisters.find(r => getRegisterId(r) === selectedId);
    state.selectedCashRegisterLabel = selected ? getRegisterLabel(selected) : "";
    pushModel();
  });
  document.getElementById("note").addEventListener("input", e => {
    state.note = e.target.value;
    pushModel();
  });
  document.getElementById("reviewBtn").addEventListener("click", () => {
    calculateOnly();
    if (!String(state.selectedCashRegisterId || "").trim()) {
      alert("Please select cash register first.");
      return;
    }
    if (Number(state.total || 0) <= 0) {
      alert("Please enter cash count first.");
      return;
    }
    const usedLines = state.lines.filter(x => Number(x.quantity || 0) > 0);
    document.getElementById("reviewBox").innerHTML = `
      <h3>Review Cash Operation</h3>
      <p><b>Operation:</b> ${operationLabel(state.operationType)}</p>
      <p><b>Cash Register:</b> ${state.selectedCashRegisterLabel}</p>
      <p><b>Total:</b> ${money(state.total)} EUR</p>
      <p><b>Note:</b> ${state.note || "-"}</p>

      <table style="width:100%; border-collapse:collapse; margin-top:10px;">
        <thead>
          <tr>
            <th style="text-align:left;">Denomination</th>
            <th style="text-align:right;">Quantity</th>
            <th style="text-align:right;">Amount</th>
          </tr>
        </thead>
        <tbody>
          ${usedLines.map(row => `
            <tr>
              <td>${money(row.denominationValue)} EUR</td>
              <td style="text-align:right;">${row.quantity}</td>
              <td style="text-align:right;">${money(row.amount)} EUR</td>
            </tr>
          `).join("")}
        </tbody>
      </table>
    `;
    document.getElementById("reviewBox").classList.remove("hidden");
    document.getElementById("saveBtn").classList.remove("hidden");
    document.getElementById("backBtn").classList.remove("hidden");
    document.getElementById("reviewBtn").classList.add("hidden");
    pushModel();
  });
  document.getElementById("backBtn").addEventListener("click", () => {
    document.getElementById("reviewBox").classList.add("hidden");
    document.getElementById("saveBtn").classList.add("hidden");
    document.getElementById("backBtn").classList.add("hidden");
    document.getElementById("reviewBtn").classList.remove("hidden");
  });
  document.getElementById("saveBtn").addEventListener("click", () => {
    calculateOnly();
    appsmith.updateModel({
      operationType: state.operationType,
      selectedCashRegisterId: state.selectedCashRegisterId,
      selectedCashRegisterLabel: state.selectedCashRegisterLabel,
      note: state.note,
      lines: state.lines,
      total: state.total
    });
    appsmith.triggerEvent("onSave");
  });
}
appsmith.onReady(() => {
  state.cashRegisters = appsmith.model.cashRegisters || [];
  renderRegisters();
  renderAllMoney();
  bindEvents();
  pushModel();
});
appsmith.onModelChange(model => {
  const currentSelectedId = state.selectedCashRegisterId;
  const currentSelectedLabel = state.selectedCashRegisterLabel;
  if (model?.cashRegisters) {
    state.cashRegisters = model.cashRegisters;
  }
  state.selectedCashRegisterId = currentSelectedId;
  state.selectedCashRegisterLabel = currentSelectedLabel;
  renderRegisters();
  const select = document.getElementById("cashRegister");
  select.value = String(state.selectedCashRegisterId || "");
});

